'use strict';

let instanceIntegrationState={items:[],credential_storage_ready:true,available:true},integrationContext=null;

const integrationDefinitions={
 ringcentral:{label:'RingCentral',group:'communications',summary:'Calls, voicemail, SMS and fax in the clinical workspace.',auth:'oauth',capabilities:['Calls','SMS','Fax','Voicemail'],apiCapabilities:['voice','sms','fax','voicemail','call_events']},
 gmail:{label:'Gmail referrals',group:'communications',summary:'Receive referral email and attachments into a reviewed intake queue.',auth:'oauth',capabilities:['Referral email','Attachments'],apiCapabilities:['referral_email','attachments','threaded_reply']},
 claude:{label:'Claude',group:'ai',summary:'Use this clinic’s Anthropic API key for reviewed extraction and drafting.',auth:'api_key',capabilities:['Drafting','Structured extraction'],apiCapabilities:['document_classification','structured_extraction','draft_summary','draft_response']},
 healthclinics:{label:'HealthClinics',group:'scheduling',summary:'Authorize HealthClinics to read availability and create or update appointments through this EHR’s API.',auth:'oauth_client',capabilities:['Availability','Booking','Reschedule','Cancel'],apiCapabilities:['scheduling_availability_read','scheduling_appointments_read','scheduling_appointments_write','scheduling_webhooks']}
};
const integrationProviderAliases={anthropic:'claude',anthropic_claude:'claude',google_gmail:'gmail',ring_central:'ringcentral',health_clinics:'healthclinics'};
const integrationProvider=value=>integrationProviderAliases[value]||value;
const integrationRecord=provider=>instanceIntegrationState.items.find(item=>integrationProvider(item.provider)===provider);
const integrationStateLabel=item=>!item?'Not configured':item.enabled?'Active':item.status==='revoked'?'Revoked':item.credential_stored?'Setup saved':'Setup incomplete';
const integrationStatusClass=item=>item?.enabled?'ready':item?.last_error?'blocked':'';
const integrationCanManage=()=>me?.role==='owner'||['partner_admin','workflow_manager'].includes(me?.delegated_role);

async function integrationList(){
 try{return await api('/api/v1/integrations');}
 catch(error){return {items:[],credential_storage_ready:true,available:false,error:error.message};}
}
function integrationCard(provider){
 const definition=integrationDefinitions[provider],item=integrationRecord(provider),status=integrationStateLabel(item),canManage=integrationCanManage();
 return `<article class="integration-card ${integrationStatusClass(item)}" data-integration-provider="${esc(provider)}"><header><div class="integration-mark" aria-hidden="true">${provider==='ringcentral'?'☎':provider==='gmail'?'✉':provider==='claude'?'✦':'↔'}</div><div><h3>${esc(definition.label)}</h3><p>${esc(definition.summary)}</p></div><span class="status-badge">${esc(status)}</span></header><div class="integration-capabilities">${definition.capabilities.map(capability=>`<span>${esc(capability)}</span>`).join('')}</div>${item?.last_error?`<p role="alert">${esc(item.last_error)}</p>`:''}<footer>${item?.last_test_at?`<small>Last local credential check ${esc(date(item.last_test_at))}</small>`:'<small>Settings and credentials stay in this EHR instance.</small>'}${canManage?`<button type="button" data-integration-manage="${esc(provider)}">${item?'Manage':'Configure'}</button>`:''}</footer></article>`;
}
function nativeBookingCard(profile){
 const enabled=profile?.enabled,publicUrl=enabled&&profile.public_slug?`${location.origin}/book/${encodeURIComponent(profile.public_slug)}`:null;
 return `<article class="integration-card native-booking ${enabled?'ready':''}"><header><div class="integration-mark" aria-hidden="true">▦</div><div><h3>SunCharts online booking</h3><p>Clinic-branded public booking backed directly by this EHR’s availability and conflict checks.</p></div><span class="status-badge">${enabled?'Active':'Not configured'}</span></header><div class="integration-capabilities"><span>Public availability</span><span>Conflict checks</span><span>Intake trigger</span><span>Reschedule workflow</span></div><footer>${publicUrl?`<a href="${esc(publicUrl)}" target="_blank" rel="noopener">Open booking page ↗</a>`:'<small>No separate scheduling service is required.</small>'}${integrationCanManage()?'<button type="button" data-integration-booking>Manage booking</button>':''}</footer></article>`;
}
function authorizedApplications({grants,clients}){
 const activeGrants=(grants.items||[]).filter(grant=>!grant.revoked_at),registered=clients.items||[];
 return `<section class="integration-section"><div class="section-head"><div><p class="eyebrow">INSTANCE ACCESS</p><h2>Authorized applications</h2><p>Applications approved to call this EHR. Vendor credentials above are separate and never leave this instance.</p></div></div>${activeGrants.map(grant=>`<article class="integration-access-row"><div><b>${esc(grant.name)}</b><small>${grant.name==='SunCharts'?'SunCharts identity and managed-instance access':esc(grant.scope.split(' ').map(scope=>scopeNames[scope]||scope).join(' · '))}</small></div><button type="button" data-revoke="${esc(grant.id)}">Revoke</button></article>`).join('')||'<p class="muted">No user-authorized applications.</p>'}${me?.role==='owner'?`<details class="integration-registered"><summary>Registered OAuth applications · ${registered.length}</summary>${registered.map(client=>`<div class="integration-access-row"><div><b>${esc(client.name)}</b><small>${esc(new URL(client.redirect_uri).origin)}</small></div>${client.disabled?'<span class="status-badge">Disabled</span>':`<button type="button" data-disable-client="${esc(client.id)}">Disable</button>`}</div>`).join('')||'<p>No registered applications.</p>'}</details>`:''}</section>`;
}
async function showInstanceIntegrations(context){
 integrationContext=context;const [connections,previsit]=await Promise.all([integrationList(),api('/api/v1/previsit/settings').catch(()=>({profile:null}))]);
 instanceIntegrationState={items:connections.items||[],credential_storage_ready:connections.credential_storage_ready!==false,available:connections.available!==false,error:connections.error};
 showTool('Integrations');$('tools').className='integration-workspace';
 $('tools').innerHTML=`<header class="integration-hero"><div><p class="eyebrow">THIS SUNCHARTS EHR INSTANCE</p><h2>Integrations</h2><p>Connect the services this practice uses. Credentials, tokens, workflow settings and audit history remain inside this EHR instance.</p></div><button type="button" data-integration-refresh>Refresh status</button></header>${!instanceIntegrationState.available?`<div class="notice"><b>Integration setup is being upgraded</b><p>${esc(instanceIntegrationState.error||'The instance-local integration registry is not available yet.')}</p></div>`:''}${!instanceIntegrationState.credential_storage_ready?'<div class="notice error"><b>Credential storage unavailable</b><p>Restore this EHR instance’s credential encryption key before saving or rotating any provider secret.</p></div>':''}<section class="integration-section"><div class="section-head"><div><p class="eyebrow">PATIENT ACCESS</p><h2>Booking and scheduling partners</h2><p>SunCharts owns the schedule. External partners use this instance’s authorized API to read availability and update appointments.</p></div></div><div class="integration-grid">${nativeBookingCard(previsit.profile)}${integrationCard('healthclinics')}</div></section><section class="integration-section"><div class="section-head"><div><p class="eyebrow">COMMUNICATIONS</p><h2>Calls, messages and referrals</h2><p>Bring incoming communication into reviewed patient and referral work queues.</p></div></div><div class="integration-grid">${integrationCard('ringcentral')}${integrationCard('gmail')}</div></section><section class="integration-section"><div class="section-head"><div><p class="eyebrow">CLINIC-OWNED AI</p><h2>Assisted documentation</h2><p>AI results remain drafts until a person reviews them. The clinic supplies and governs its own provider account.</p></div></div><div class="integration-grid">${integrationCard('claude')}</div></section>${authorizedApplications(context)}<section class="integration-section compact"><div class="section-head"><div><h2>SunCharts platform services</h2><p>Identity, managed hosting, payments and support are separate from the clinic-owned integrations above.</p></div><button type="button" data-connect-services>Open platform services</button></div>${typeof connectStatusCard==='function'?connectStatusCard(context.connection):''}</section><div id="integration-editor"></div>`;
}

function integrationEditor(provider){
 const definition=integrationDefinitions[provider],item=integrationRecord(provider),host=$('integration-editor');if(!definition||!host)return;
 const oauth=definition.auth==='oauth',apiKey=definition.auth==='api_key',partner=definition.auth==='oauth_client',oauthClients=(integrationContext?.clients?.items||[]).filter(client=>!client.disabled),actionReady=partner||item?.credential_stored;
 host.innerHTML=`<div class="integration-drawer-backdrop" data-integration-close></div><aside class="integration-drawer" aria-label="${esc(definition.label)} settings"><div class="detail-titlebar"><div><p class="eyebrow">INSTANCE INTEGRATION</p><h2>${esc(definition.label)}</h2></div><button type="button" data-integration-close aria-label="Close">Close</button></div><p>${esc(definition.summary)}</p>${partner?`<div class="mapping-notice"><b>HealthClinics connects to SunCharts</b><p>HealthClinics reads availability and writes appointments through this EHR’s OAuth API. This EHR does not sign in to or pull from HealthClinics.</p></div>`:''}${item?`<div class="integration-detail-status"><span class="status-badge">${esc(integrationStateLabel(item))}</span>${item.credential_hint?`<span>Saved credential ${esc(item.credential_hint)}</span>`:''}<span>Settings v${item.version}</span></div>`:''}${integrationCanManage()?`<form id="integration-settings-form" data-provider="${esc(provider)}" data-id="${esc(item?.id||'')}" data-version="${item?.version||''}"><label>Connection name<input name="label" required maxlength="120" value="${esc(item?.label||definition.label)}"></label>${oauth?`<div class="form-grid"><label>OAuth client ID<input name="client_id" required maxlength="512" autocomplete="off" value="${esc(item?.config?.client_id||'')}"></label><label>OAuth client secret<input name="secret" type="password" ${item?.credential_stored?'':'required'} maxlength="1024" autocomplete="new-password" value=""></label></div>${provider==='ringcentral'?`<label>RingCentral environment<select name="environment"><option value="production" ${item?.config?.environment!=='sandbox'?'selected':''}>Production</option><option value="sandbox" ${item?.config?.environment==='sandbox'?'selected':''}>Sandbox</option></select></label>`:''}<p class="muted">Leave the secret blank to keep the saved value. OAuth authorization starts only after application credentials are saved.</p>`:apiKey?`<label>Anthropic API key ${item?.credential_stored?'(leave blank to keep saved key)':''}<input name="secret" type="password" ${item?.credential_stored?'':'required'} maxlength="1024" autocomplete="new-password"></label><label>Model<input name="model" maxlength="120" value="${esc(item?.config?.model||'')}"></label><p class="muted">The clinic is responsible for its Anthropic agreement, configuration and intended data use. SunCharts does not supply this key or AI usage.</p>`:partner?`<label>Authorized EHR application<select name="oauth_client_id" required><option value="">Choose the HealthClinics OAuth application</option>${oauthClients.map(client=>`<option value="${esc(client.id)}" ${client.id===item?.config?.oauth_client_id?'selected':''}>${esc(client.name)} · ${esc(new URL(client.redirect_uri).origin)}</option>`).join('')}</select></label>${oauthClients.length?'<p class="muted">HealthClinics completes authorization against this application. The integration becomes active only after its grant exists.</p>':'<p class="notice">Register the HealthClinics OAuth application below before configuring this scheduling partner.</p>'}`:''}<button type="submit" class="primary">${item?'Save settings':partner?'Register scheduling partner':'Save connection'}</button></form>`:''}${item&&integrationCanManage()?`<section class="integration-drawer-actions"><h3>Connection actions</h3><div class="actions">${actionReady?`<button type="button" data-integration-action="test" data-integration-id="${esc(item.id)}" data-version="${item.version}">${partner?'Check OAuth application':'Check saved credential'}</button>`:''}${oauth?`<button type="button" data-integration-oauth="${esc(item.id)}">Authorize account</button>`:''}${actionReady?`<button type="button" data-integration-action="${item.enabled?'disable':'enable'}" data-integration-id="${esc(item.id)}" data-version="${item.version}" class="${item.enabled?'':'primary'}">${item.enabled?'Disable':'Enable'}</button>`:''}<button type="button" data-integration-action="revoke" data-integration-id="${esc(item.id)}" data-version="${item.version}">Revoke</button></div><p class="muted">${partner?'The scheduling partner uses the EHR OAuth application and grant shown here.':'A local credential check confirms encrypted storage can be read. It does not claim that the external provider accepted the credential.'}</p></section>`:''}${item?'<section id="integration-adapter-panel" class="integration-adapter-panel"><p class="muted">Loading adapter operations…</p></section>':''}</aside>`;
 if(item)void integrationAdapterPanel(provider,item);
}
function closeIntegrationEditor(){const host=$('integration-editor');if(host)host.replaceChildren();}

document.addEventListener('submit',event=>{
 const form=event.target;if(form.id!=='integration-settings-form')return;event.preventDefault();event.stopImmediatePropagation();
 run(async()=>{const values=Object.fromEntries(new FormData(form)),provider=form.dataset.provider,item=integrationRecord(provider),definition=integrationDefinitions[provider],credential=values.secret||null,config={};if(values.client_id)config.client_id=values.client_id;if(values.model)config.model=values.model;if(values.environment)config.environment=values.environment;if(values.oauth_client_id)config.oauth_client_id=values.oauth_client_id;const body={label:values.label,capabilities:definition.apiCapabilities,config};if(!item)body.provider=provider;if(credential)body.credential=credential;await api(item?`/api/v1/integrations/${item.id}`:'/api/v1/integrations',item?'PUT':'POST',body,item?.version);closeIntegrationEditor();await showInstanceIntegrations(integrationContext);integrationEditor(provider);notice(`${definition.label} settings saved in this EHR instance.`);});
},true);
document.addEventListener('click',event=>{
 const button=event.target.closest?.('[data-integration-manage],[data-integration-close],[data-integration-booking],[data-integration-refresh],[data-integration-action],[data-integration-oauth]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();
 run(async()=>{if(button.hasAttribute('data-integration-close')){closeIntegrationEditor();return;}if(button.hasAttribute('data-integration-booking')){await showPrevisit();return;}if(button.hasAttribute('data-integration-refresh')){await showApps();notice('Instance integration status refreshed.');return;}if(button.dataset.integrationManage){integrationEditor(button.dataset.integrationManage);return;}if(button.dataset.integrationOauth){const item=instanceIntegrationState.items.find(candidate=>candidate.id===button.dataset.integrationOauth),provider=integrationProvider(item?.provider),path=provider==='ringcentral'?`/api/v1/integrations/ringcentral/${item.id}/oauth/start`:provider==='gmail'?`/api/v1/integrations/${item.id}/gmail/oauth/start`:null;if(!path)throw new Error('This adapter does not use provider OAuth setup.');const callback=provider==='ringcentral'?'/api/v1/integrations/ringcentral/oauth/callback':'/api/v1/integrations/gmail/oauth/callback',result=await api(path,'POST',{redirect_uri:`${location.origin}${callback}`});if(result.authorization_url){location.assign(result.authorization_url);return;}throw new Error('The provider did not return an authorization page.');}const id=button.dataset.integrationId,action=button.dataset.integrationAction;await api(`/api/v1/integrations/${id}/actions`,'POST',{action},Number(button.dataset.version));closeIntegrationEditor();await showApps();notice(`Integration ${human(action)} recorded.`);});
},true);

async function integrationAdapterPanel(provider,item){
 const panel=$('integration-adapter-panel');if(!panel)return;
 if(provider==='ringcentral'){
  panel.innerHTML=`<h3>RingCentral operations</h3><p>Authorize this practice, verify the live account, then start the outbound WebSocket feed. No public EHR URL or inbound firewall rule is required.</p><div class="actions"><button data-adapter-test="ringcentral" data-id="${esc(item.id)}">Test live account</button><button data-ringcentral-subscribe="${esc(item.id)}">Start outbound live feed</button><button data-open-integration-inbox="communications">Open communications inbox</button><button class="primary" data-open-outbound="ringcentral">Send or review drafts</button></div><details><summary>Optional webhook delivery</summary><p class="muted">Use only when the practice intentionally exposes a verified public EHR callback. Outbound WebSocket is the default.</p><form id="ringcentral-webhook-form" data-id="${esc(item.id)}"><label>Public EHR address<input name="public_base_url" type="url" required value="${esc(location.origin)}"></label><button type="submit">Use webhook instead</button></form></details>`;return;
 }
 if(provider==='gmail'){
  const status=await api(`/api/v1/integrations/${item.id}/gmail/watch`).catch(error=>({watch:null,error:error.message}));if(!$('integration-adapter-panel'))return;
  panel.innerHTML=`<h3>Referral mailbox operations</h3>${status.watch?`<p><b>${esc(status.watch.mailbox)}</b> · ${status.watch.enabled?'Active':'Inactive'} · ${status.watch.delivery_mode==='pubsub'?'Google Pub/Sub push':`Outbound polling every ${status.watch.poll_seconds||300} seconds`}</p>${status.watch.next_poll_at?`<p class="muted">Next poll ${esc(date(status.watch.next_poll_at))}</p>`:''}${status.watch.last_error?`<p role="alert">${esc(status.watch.last_error)}</p>`:''}`:'<p>Use outbound polling for the simplest secure setup. It requires no public EHR URL or inbound firewall rule.</p>'}<div class="actions"><button data-gmail-sync="${esc(item.id)}">Sync now</button><button data-open-integration-inbox="referrals">Open referral inbox</button><button class="primary" data-open-outbound="gmail">Reply or review drafts</button></div><details open><summary>Mailbox delivery</summary><form id="gmail-watch-form" data-id="${esc(item.id)}"><label>Delivery mode<select name="delivery_mode"><option value="poll" ${status.watch?.delivery_mode!=='pubsub'?'selected':''}>Outbound polling (recommended)</option><option value="pubsub" ${status.watch?.delivery_mode==='pubsub'?'selected':''}>Google Pub/Sub push</option></select></label><label>Gmail labels<input name="label_ids" placeholder="INBOX, REFERRALS" value="${esc((status.watch?.label_ids||[]).join(', '))}"></label><label>Polling interval (seconds)<input name="poll_seconds" type="number" min="60" max="3600" value="${status.watch?.poll_seconds||300}"></label><details><summary>Pub/Sub fields — only for push mode</summary><label>Topic name<input name="topic_name" placeholder="projects/example/topics/referrals"></label><label>Public EHR address<input name="public_base_url" type="url" value="${esc(location.origin)}"></label><label>OIDC audience<input name="oidc_audience" type="url" value="${esc(location.origin)}"></label><label>Push service account<input name="oidc_service_account" type="email" placeholder="gmail-push@example.iam.gserviceaccount.com"></label></details><button type="submit">Save mailbox delivery</button></form></details>`;return;
 }
 if(provider==='claude'){
  panel.innerHTML='<h3>Draft review operations</h3><p>Claude can create drafts only. Staff must review every result before it changes a pathway or is used elsewhere.</p><button data-open-ai-review>Open AI review queue</button>';return;
 }
 panel.innerHTML='<p class="muted">This partner operates through the EHR OAuth API and its authorized application record.</p>';
}

let integrationInboxState={tab:'communications',integrations:[],patients:[],communications:[],referrals:[],detail:null};
const integrationPatientLabel=patient=>patient.display_name||[patient.family_name,patient.given_name].filter(Boolean).join(', ')||patient.mrn||patient.id;
const integrationPatientOptions=selected=>`<option value="">No patient selected</option>${integrationInboxState.patients.map(patient=>`<option value="${esc(patient.id)}" ${patient.id===selected?'selected':''}>${esc(integrationPatientLabel(patient))}${patient.mrn?` · ${esc(patient.mrn)}`:''}</option>`).join('')}`;
function integrationQueueRow(item,type){
 const title=type==='communications'?`${human(item.event_kind||'message')} · ${item.occurred_at?date(item.occurred_at):'Received'}`:item.subject||'Referral email';
 const summary=type==='communications'?item.event_uri||'Inbound RingCentral event':`${item.sender||'Unknown sender'}${item.snippet?` · ${item.snippet}`:''}`;
 return `<button class="integration-queue-row" data-${type==='communications'?'communication-event':'referral-entry'}="${esc(item.id)}"><span class="integration-kind">${type==='communications'?esc((item.event_kind||'message').slice(0,2).toUpperCase()):'✉'}</span><span><b>${esc(title)}</b><small>${esc(summary)}</small></span><span><span class="status-badge">${esc(human(item.status||'pending_review'))}</span>${type==='referrals'&&item.attachment_count?`<small>${item.attachment_count} attachment${item.attachment_count===1?'':'s'}</small>`:''}</span></button>`;
}
function integrationInboxDetail(){
 const detail=integrationInboxState.detail;if(!detail)return '<section class="integration-empty"><h3>Select an item to review</h3><p>Nothing is linked to a patient or dismissed until a person reviews it.</p></section>';
 if(detail.type==='communications')return `<section class="integration-review-panel"><p class="eyebrow">REVIEW COMMUNICATION</p><h3>${esc(human(detail.event.event_kind||'message'))}</h3><p>${detail.event.occurred_at?esc(date(detail.event.occurred_at)):''}</p><pre>${esc(JSON.stringify(detail.payload,null,2))}</pre>${detail.event.status==='pending_review'?`<form id="communication-review-form" data-integration="${esc(detail.integration)}" data-event="${esc(detail.event.id)}"><label>Link to patient<select name="patient_id">${integrationPatientOptions(detail.event.linked_patient_id)}</select></label><label>Review note<textarea name="reason" required maxlength="500"></textarea></label><div class="actions"><button class="primary" name="action" value="review">Mark reviewed</button><button name="action" value="ignore">Ignore</button></div></form>`:'<p class="notice">This communication has already been reviewed.</p>'}</section>`;
 return `<section class="integration-review-panel"><p class="eyebrow">REFERRAL EMAIL</p><h3>${esc(detail.subject||'Referral email')}</h3><p><b>From:</b> ${esc(detail.sender||'Unknown')}</p>${detail.body_text?`<div class="referral-message-body">${esc(detail.body_text)}</div>`:`<p>${esc(detail.snippet||'')}</p>`}${detail.attachments?.length?`<h4>Attachments</h4><ul>${detail.attachments.map(file=>`<li>${esc(file.filename||file.part_id)} · ${esc(file.mime_type||'file')} · ${Number(file.size_bytes||0).toLocaleString()} bytes</li>`).join('')}</ul>`:'<p class="muted">No attachments.</p>'}${detail.status==='new'?`<form id="referral-review-form" data-integration="${esc(detail.integration)}" data-entry="${esc(detail.id)}"><label>Link to patient<select name="patient_id">${integrationPatientOptions(detail.patient_id)}</select></label><label>Review note<textarea name="reason" required maxlength="500"></textarea></label><div class="actions"><button class="primary" name="action" value="link">Link referral</button><button name="action" value="dismiss">Dismiss</button></div></form>`:'<p class="notice">This referral has already been reviewed.</p>'}</section>`;
}
function renderIntegrationInbox(){
 const host=$('tools'),tab=integrationInboxState.tab,items=tab==='communications'?integrationInboxState.communications:integrationInboxState.referrals,provider=tab==='communications'?'RingCentral':'Gmail';
 host.className='integration-operations';host.innerHTML=`<header class="task-workspace-head"><div><p class="eyebrow">PATIENT CARE</p><h2>Intake inbox</h2><p>Review inbound communications before linking them to a patient record.</p></div><div class="actions"><button class="primary" data-open-outbound="${tab==='communications'?'ringcentral':'gmail'}">Send & review</button><button data-refresh-integration-inbox>Refresh</button></div></header><nav class="workspace-tabs" aria-label="Intake inbox views"><button class="${tab==='communications'?'active':''}" data-inbox-tab="communications">Communications <span>${integrationInboxState.communications.filter(item=>item.status==='pending_review').length}</span></button><button class="${tab==='referrals'?'active':''}" data-inbox-tab="referrals">Referral email <span>${integrationInboxState.referrals.filter(item=>item.status==='new').length}</span></button></nav><div class="integration-queue-layout"><section class="integration-queue-list"><div class="section-head"><div><h3>${provider} queue</h3><p>${items.length} recent item${items.length===1?'':'s'}</p></div><button data-open-integrations>Setup</button></div>${items.map(item=>integrationQueueRow(item,tab)).join('')||`<div class="integration-empty"><h3>No ${tab==='communications'?'communications':'referral emails'} waiting</h3><p>${integrationRecord(tab==='communications'?'ringcentral':'gmail')?'New items appear here after the adapter receives them.':`Configure ${provider} in Integrations first.`}</p></div>`}</section>${integrationInboxDetail()}</div>`;
}
async function showIntegrationInbox(tab='communications'){
 showTool('Intake inbox');$('tools').innerHTML='<p class="muted">Loading intake queues…</p>';const [registry,patientPage]=await Promise.all([integrationList(),api('/api/v1/patients').catch(()=>({items:[]}))]);instanceIntegrationState={...instanceIntegrationState,items:registry.items||[]};const ring=integrationRecord('ringcentral'),gmail=integrationRecord('gmail');const [communications,referrals]=await Promise.all([ring?api(`/api/v1/integrations/ringcentral/${ring.id}/inbox`).catch(()=>({items:[]})):Promise.resolve({items:[]}),gmail?api(`/api/v1/integrations/${gmail.id}/gmail/referrals`).catch(()=>({items:[]})):Promise.resolve({items:[]})]);integrationInboxState={tab,integrations:registry.items||[],patients:patientPage.items||[],communications:communications.items||[],referrals:referrals.items||[],detail:null};renderIntegrationInbox();
}

let outboundState={provider:'ringcentral',integrations:[],items:[],detail:null};
const outboundProviderLabel=provider=>provider==='gmail'?'Gmail':'RingCentral';
const outboundCanReview=()=>['owner','clinician'].includes(me?.role)||['partner_admin','workflow_manager'].includes(me?.delegated_role);
const outboundSplit=value=>String(value||'').split(',').map(item=>item.trim()).filter(Boolean);
function outboundRow(item){return `<button class="integration-queue-row ${outboundState.detail?.id===item.id?'selected':''}" data-outbound-draft="${esc(item.id)}"><span class="integration-kind">${outboundState.provider==='gmail'?'EMAIL':esc(String(item.kind||'').toUpperCase())}</span><span><b>${esc(item.subject||human(item.kind||'communication'))}</b><small>${item.to?.length?esc(item.to.join(', ')):`Created ${esc(date(item.created_at))}`}</small></span><span class="status-badge ${esc(item.status)}">${esc(human(item.status))}</span></button>`;}
function ringCompose(integration){return `<form id="ringcentral-outbound-form" data-id="${esc(integration.id)}"><div class="form-grid"><label>Action<select name="kind" data-ringcentral-kind><option value="sms">Send SMS</option><option value="ringout">Start phone call</option><option value="fax">Send PDF fax</option></select></label><label>Recipient phone (E.164)<input name="recipient" required placeholder="+15551234567" pattern="\\+[0-9]{8,15}"></label></div><div data-ringcentral-sms><label>Practice SMS number (E.164)<input name="sender" placeholder="+15557654321"></label><label>Message<textarea name="text" maxlength="1000"></textarea></label></div><div data-ringcentral-fax hidden><label>PDF document<input name="document" type="file" accept="application/pdf"></label><label>Cover page note<textarea name="cover_page_text" maxlength="1024"></textarea></label></div><label class="review-ack"><input type="checkbox" name="recipient_reviewed" required> I reviewed the recipient. This creates a draft only.</label><button class="primary" type="submit">Create draft for review</button></form>`;}
function gmailCompose(integration){return `<form id="gmail-outbound-form" data-id="${esc(integration.id)}"><div class="form-grid"><label>To (comma separated)<input name="to" type="text" required placeholder="referrals@example.org"></label><label>Cc (optional)<input name="cc" type="text"></label></div><label>Subject<input name="subject" required maxlength="500"></label><label>Message<textarea name="body_text" required maxlength="65536"></textarea></label><label>Attachments (optional, 10 maximum)<input name="attachments" type="file" multiple></label><label class="review-ack"><input type="checkbox" name="recipient_reviewed" required> I reviewed the recipients. This creates a draft only.</label><button class="primary" type="submit">Create draft for review</button></form>`;}
function outboundDetail(){const value=outboundState.detail;if(!value)return '<section class="integration-empty"><h3>Select a draft</h3><p>Review its recipient and content before approving it.</p></section>';if(outboundState.provider==='ringcentral'){const draft=value.draft||{},payload=value.payload||{},canReview=outboundCanReview();return `<section class="integration-review-panel"><p class="eyebrow">REVIEWED ${esc(String(draft.kind||'COMMUNICATION').toUpperCase())}</p><h3>${esc(human(draft.status))}</h3><dl class="outbound-review-summary"><div><dt>Recipient</dt><dd>${esc(payload.recipient)}</dd></div>${payload.sender?`<div><dt>From</dt><dd>${esc(payload.sender)}</dd></div>`:''}${payload.filename?`<div><dt>Document</dt><dd>${esc(payload.filename)}</dd></div>`:''}</dl>${payload.text?`<pre>${esc(payload.text)}</pre>`:''}${payload.cover_page_text?`<p>${esc(payload.cover_page_text)}</p>`:''}${draft.last_error?`<div class="notice error"><b>Provider needs review</b><p>${esc(draft.last_error)}</p></div>`:''}${draft.status==='draft'&&canReview?`<form id="ringcentral-approve-form" data-id="${esc(draft.id)}"><label>Re-enter recipient to confirm<input name="confirmed_recipient" required value="${esc(payload.recipient)}"></label><label>Approval note<input name="reason" required maxlength="500"></label><button class="primary">Approve recipient and content</button></form>`:''}${draft.status==='approved'&&canReview?`<form id="ringcentral-send-form" data-id="${esc(draft.id)}"><div class="notice warning"><b>Separate send gate</b><p>This action contacts RingCentral. Provider acceptance does not prove delivery or call connection.</p></div><button class="primary">Send approved ${esc(human(draft.kind))}</button></form>`:''}${draft.status==='accepted'&&canReview?`<button data-ringcentral-refresh-outbound="${esc(draft.id)}">Refresh provider status</button>`:''}<details><summary>Audit history</summary>${(value.events||[]).map(event=>`<p><b>${esc(human(event.action))}</b> · ${esc(date(event.created_at))}</p>`).join('')||'<p>No events.</p>'}</details></section>`;}const item=value,canReview=outboundCanReview();return `<section class="integration-review-panel"><p class="eyebrow">REVIEWED EMAIL</p><h3>${esc(item.subject)}</h3><dl class="outbound-review-summary"><div><dt>To</dt><dd>${esc((item.to_addresses||[]).join(', '))}</dd></div>${item.cc_addresses?.length?`<div><dt>Cc</dt><dd>${esc(item.cc_addresses.join(', '))}</dd></div>`:''}<div><dt>Status</dt><dd>${esc(human(item.status))}</dd></div></dl><pre>${esc(item.body_text)}</pre>${item.attachments?.length?`<p>${item.attachments.length} reviewed attachment${item.attachments.length===1?'':'s'}</p>`:''}${item.last_error?`<div class="notice error"><b>Send needs review</b><p>${esc(item.last_error)}</p></div>`:''}${item.status==='draft'&&canReview?`<form id="gmail-outbound-action-form" data-id="${esc(item.id)}" data-version="${item.version}"><label>Approval note<input name="reason" required maxlength="500"></label><div class="actions"><button class="primary" name="action" value="approve">Approve content</button><button name="action" value="cancel">Cancel draft</button></div></form>`:''}${item.status==='approved'&&canReview?`<form id="gmail-outbound-action-form" data-id="${esc(item.id)}" data-version="${item.version}"><div class="notice warning"><b>Separate send gate</b><p>This action sends through the clinic-owned Gmail account.</p></div><label>Send note<input name="reason" required maxlength="500"></label><button class="primary" name="action" value="send">Send approved email</button></form>`:''}${item.receipt?`<p class="notice"><b>Gmail accepted the message</b><br>${esc(item.receipt.gmail_message_id||'Provider receipt recorded')}</p>`:''}</section>`;}
function renderOutboundWorkspace(){const provider=outboundState.provider,integration=outboundState.integrations.find(item=>integrationProvider(item.provider)===provider),compose=integration?(provider==='gmail'?gmailCompose(integration):ringCompose(integration)):`<div class="notice"><b>${outboundProviderLabel(provider)} is not configured</b><p>Open Integrations to connect the clinic-owned account first.</p></div>`;$('tools').className='integration-operations';$('tools').innerHTML=`<header class="task-workspace-head"><div><p class="eyebrow">COMMUNICATIONS</p><h2>Send & review</h2><p>Create drafts, verify recipients, approve, then send through this EHR instance.</p></div><button data-refresh-outbound>Refresh</button></header><nav class="workspace-tabs" aria-label="Outbound communication providers"><button class="${provider==='ringcentral'?'active':''}" data-outbound-provider="ringcentral">Calls, SMS & fax</button><button class="${provider==='gmail'?'active':''}" data-outbound-provider="gmail">Email</button></nav><div class="notice warning"><b>Nothing sends automatically</b><p>Workflow and AI modules can prepare drafts, but a person must review and approve them. Sending is a separate action.</p></div><details class="ai-compose" ${outboundState.items.length?'':'open'}><summary>Create a ${esc(outboundProviderLabel(provider))} draft</summary>${compose}</details><div class="integration-queue-layout"><section class="integration-queue-list"><div class="section-head"><div><h3>Draft queue</h3><p>${outboundState.items.length} recent item${outboundState.items.length===1?'':'s'}</p></div></div>${outboundState.items.map(outboundRow).join('')||'<div class="integration-empty"><h3>No drafts yet</h3><p>Create a reviewed draft above or from Workflow Studio.</p></div>'}</section>${outboundDetail()}</div>`;}
async function showOutboundWorkspace(provider='ringcentral'){showTool('Send & review');$('tools').innerHTML='<p class="muted">Loading communication drafts…</p>';const registry=await integrationList();instanceIntegrationState={...instanceIntegrationState,items:registry.items||[]};const integration=(registry.items||[]).find(item=>integrationProvider(item.provider)===provider);let items=[];if(integration)items=(await api(provider==='gmail'?`/api/v1/integrations/${integration.id}/gmail/outbound-drafts`:`/api/v1/integrations/ringcentral/${integration.id}/outbound`).catch(()=>({items:[]}))).items||[];outboundState={provider,integrations:registry.items||[],items,detail:null};renderOutboundWorkspace();}
async function outboundFile(file){if(!file)return null;const bytes=new Uint8Array(await file.arrayBuffer()),parts=[];for(let index=0;index<bytes.length;index+=0x8000)parts.push(String.fromCharCode(...bytes.subarray(index,index+0x8000)));return btoa(parts.join(''));}

let aiReviewState={items:[],integrations:[],detail:null};
function aiDraftRow(item){return `<button class="integration-queue-row" data-ai-draft="${esc(item.id)}"><span class="integration-kind">AI</span><span><b>${esc(human(item.purpose))}</b><small>${item.pathway_instance_id?`Workflow step · ${esc(item.step_key)}`:'Standalone reviewed draft'} · ${esc(item.model||'clinic model')}</small></span><span class="status-badge">${esc(human(item.status))}</span></button>`;}
function aiReviewDetail(){const detail=aiReviewState.detail;if(!detail)return '<section class="integration-empty"><h3>Select a draft to review</h3><p>AI output is never applied or sent automatically.</p></section>';const draft=detail.draft;return `<section class="integration-review-panel"><p class="eyebrow">HUMAN REVIEW REQUIRED</p><h3>${esc(human(draft.purpose))}</h3><div class="notice warning"><b>Draft only</b><p>Verify every statement against the source. Approval records review; it does not send a message or create a diagnosis.</p></div>${draft.pathway_instance_id?`<p><b>Workflow context:</b> ${esc(draft.step_key)} · instance ${esc(draft.pathway_instance_id)}</p>`:'<p class="muted">Standalone draft; no workflow step is linked.</p>'}<pre>${esc(draft.content||`Draft failed: ${draft.failure_code||'no content'}`)}</pre>${draft.status==='draft'&&(['owner','clinician'].includes(me.role)||me.delegated_role==='partner_admin')?`<form id="ai-review-form" data-id="${esc(draft.id)}" data-version="${draft.version}"><label>Review note<textarea name="reason" required maxlength="1000"></textarea></label><div class="actions"><button class="primary" name="action" value="approve">Approve reviewed draft</button><button name="action" value="reject">Reject draft</button></div></form>`:`<p class="notice">Status: ${esc(human(draft.status))}</p>`}</section>`;}
function renderAiReview(){const claude=aiReviewState.integrations.filter(item=>integrationProvider(item.provider)==='claude'&&item.enabled);$('tools').className='integration-operations';$('tools').innerHTML=`<header class="task-workspace-head"><div><p class="eyebrow">OPERATIONS</p><h2>AI review</h2><p>Create drafts with the clinic-owned Claude connection and review every result before use.</p></div><button data-refresh-ai-review>Refresh</button></header><div class="notice warning"><b>Human review is mandatory</b><p>SunCharts treats AI output as untrusted draft material. Nothing is sent, charted or applied without a person’s explicit review.</p></div><details class="ai-compose" ${aiReviewState.items.length?'':'open'}><summary>Generate a reviewed draft</summary>${claude.length?`<form id="ai-generate-form"><label>Claude connection<select name="integration_id" required>${claude.map(item=>`<option value="${esc(item.id)}">${esc(item.label)}</option>`).join('')}</select></label><label>Draft purpose<select name="purpose"><option value="structured_extraction">Structured extraction</option><option value="document_classification">Document classification</option><option value="draft_summary">Draft summary</option><option value="draft_response">Draft administrative response</option></select></label><label>Instruction<textarea name="instruction" required maxlength="4000" placeholder="Describe the reviewed output needed"></textarea></label><label>Source material<textarea name="source_text" required maxlength="65536" placeholder="Paste up to 65,536 UTF-8 bytes of source text to review"></textarea></label><div class="form-grid"><label>Workflow instance (optional)<input name="pathway_instance_id" placeholder="UUID"></label><label>Workflow step (optional)<input name="step_key" maxlength="63"></label></div><button class="primary" type="submit">Generate draft for review</button></form>`:'<p>No enabled clinic-owned Claude connection. Configure and enable one in Integrations.</p><button data-open-integrations>Open Integrations</button>'}</details><div class="integration-queue-layout"><section class="integration-queue-list"><h3>Draft queue</h3>${aiReviewState.items.map(aiDraftRow).join('')||'<div class="integration-empty"><p>No drafts yet.</p></div>'}</section>${aiReviewDetail()}</div>`;}
async function showAiReviewWorkspace(){showTool('AI review');$('tools').innerHTML='<p class="muted">Loading reviewed drafts…</p>';const [registry,drafts]=await Promise.all([integrationList(),api('/api/v1/ai/drafts').catch(()=>({items:[]}))]);instanceIntegrationState={...instanceIntegrationState,items:registry.items||[]};aiReviewState={items:drafts.items||[],integrations:registry.items||[],detail:null};renderAiReview();}

document.addEventListener('submit',event=>{
 const form=event.target;if(!['ringcentral-webhook-form','gmail-watch-form','communication-review-form','referral-review-form','ai-generate-form','ai-review-form','ringcentral-outbound-form','ringcentral-approve-form','ringcentral-send-form','gmail-outbound-form','gmail-outbound-action-form'].includes(form.id))return;event.preventDefault();event.stopImmediatePropagation();
 run(async()=>{const data=new FormData(form),values=Object.fromEntries(data);if(form.id==='ringcentral-webhook-form'){await api(`/api/v1/integrations/ringcentral/${form.dataset.id}/subscription`,'POST',{transport:'webhook',public_base_url:values.public_base_url});notice('RingCentral webhook delivery configured.');return;}if(form.id==='gmail-watch-form'){const body={delivery_mode:values.delivery_mode,label_ids:values.label_ids.split(',').map(value=>value.trim()).filter(Boolean),poll_seconds:Number(values.poll_seconds)};if(values.delivery_mode==='pubsub')Object.assign(body,{topic_name:values.topic_name,public_base_url:values.public_base_url,oidc_audience:values.oidc_audience,oidc_service_account:values.oidc_service_account});await api(`/api/v1/integrations/${form.dataset.id}/gmail/watch`,'POST',body);await integrationAdapterPanel('gmail',integrationRecord('gmail'));notice(values.delivery_mode==='poll'?'Outbound Gmail polling configured.':'Gmail Pub/Sub push configured.');return;}if(form.id==='communication-review-form'){const action=event.submitter?.value||'review';await api(`/api/v1/integrations/ringcentral/${form.dataset.integration}/inbox/${form.dataset.event}`,'POST',{action,patient_id:values.patient_id||null,reason:values.reason});await showIntegrationInbox('communications');notice('Communication review recorded.');return;}if(form.id==='referral-review-form'){const action=event.submitter?.value||'link';await api(`/api/v1/integrations/${form.dataset.integration}/gmail/referrals/${form.dataset.entry}/actions`,'POST',{action,patient_id:action==='link'?(values.patient_id||null):null,reason:values.reason});await showIntegrationInbox('referrals');notice('Referral review recorded.');return;}if(form.id==='ringcentral-outbound-form'){const body={request_id:crypto.randomUUID(),kind:values.kind,recipient:values.recipient};if(values.kind==='sms')Object.assign(body,{sender:values.sender,text:values.text});if(values.kind==='ringout'&&values.sender)body.sender=values.sender;if(values.kind==='fax'){const file=form.elements.document.files[0];if(!file||file.type!=='application/pdf')throw new Error('Choose the reviewed PDF to fax.');Object.assign(body,{filename:file.name,content_type:'application/pdf',document_base64:await outboundFile(file),cover_page_text:values.cover_page_text||''});}await api(`/api/v1/integrations/ringcentral/${form.dataset.id}/outbound`,'POST',body);await showOutboundWorkspace('ringcentral');notice('RingCentral draft created. Review and approve it before sending.');return;}if(form.id==='ringcentral-approve-form'){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='ringcentral');await api(`/api/v1/integrations/ringcentral/${integration.id}/outbound/${form.dataset.id}/approve`,'POST',{request_id:crypto.randomUUID(),confirmed_recipient:values.confirmed_recipient,reason:values.reason});await showOutboundWorkspace('ringcentral');notice('Recipient and content approved. Sending remains a separate action.');return;}if(form.id==='ringcentral-send-form'){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='ringcentral');await api(`/api/v1/integrations/ringcentral/${integration.id}/outbound/${form.dataset.id}/send`,'POST',{request_id:crypto.randomUUID()});await showOutboundWorkspace('ringcentral');notice('RingCentral accepted the request. Delivery or call connection is not yet confirmed.');return;}if(form.id==='gmail-outbound-form'){const files=[...form.elements.attachments.files];if(files.length>10)throw new Error('Choose no more than 10 attachments.');const attachments=[];for(const file of files)attachments.push({filename:file.name,mime_type:file.type||'application/octet-stream',data_base64:await outboundFile(file)});await api(`/api/v1/integrations/${form.dataset.id}/gmail/outbound-drafts`,'POST',{idempotency_key:`browser-${crypto.randomUUID()}`,inbox_id:null,to:outboundSplit(values.to),cc:outboundSplit(values.cc),subject:values.subject,body_text:values.body_text,attachments});await showOutboundWorkspace('gmail');notice('Email draft created. Review and approve it before sending.');return;}if(form.id==='gmail-outbound-action-form'){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='gmail'),action=event.submitter?.value||'cancel';await api(`/api/v1/integrations/${integration.id}/gmail/outbound-drafts/${form.dataset.id}/actions`,'POST',{action,reason:values.reason,expected_version:Number(form.dataset.version)});await showOutboundWorkspace('gmail');notice(action==='send'?'Gmail accepted the approved message.':`Email draft ${action==='approve'?'approved':'cancelled'}.`);return;}if(form.id==='ai-generate-form'){const pathway=values.pathway_instance_id||null,step=values.step_key||null;if(Boolean(pathway)!==Boolean(step))throw new Error('Workflow instance and step are required together.');if(new TextEncoder().encode(values.source_text).length>65536)throw new Error('Source material must be 65,536 UTF-8 bytes or less.');await api('/api/v1/ai/drafts','POST',{request_id:crypto.randomUUID(),integration_id:values.integration_id,purpose:values.purpose,instruction:values.instruction,source_text:values.source_text,pathway_instance_id:pathway,step_key:step});await showAiReviewWorkspace();notice('Claude draft received and queued for human review.');return;}const action=event.submitter?.value||'reject';await api(`/api/v1/ai/drafts/${form.dataset.id}/actions`,'POST',{action,reason:values.reason},Number(form.dataset.version));await showAiReviewWorkspace();notice(`Draft ${action==='approve'?'approved':'rejected'}.`);});
},true);
document.addEventListener('click',event=>{
 const button=event.target.closest?.('[data-adapter-test],[data-ringcentral-subscribe],[data-gmail-sync],[data-open-integration-inbox],[data-inbox-tab],[data-communication-event],[data-referral-entry],[data-refresh-integration-inbox],[data-open-ai-review],[data-ai-draft],[data-refresh-ai-review],[data-open-integrations],[data-open-outbound],[data-outbound-provider],[data-outbound-draft],[data-refresh-outbound],[data-ringcentral-refresh-outbound]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();
 run(async()=>{if(button.hasAttribute('data-open-integrations')){await showApps();return;}if(button.dataset.openOutbound){closeIntegrationEditor();await showOutboundWorkspace(button.dataset.openOutbound);return;}if(button.dataset.outboundProvider){await showOutboundWorkspace(button.dataset.outboundProvider);return;}if(button.hasAttribute('data-refresh-outbound')){await showOutboundWorkspace(outboundState.provider);return;}if(button.dataset.outboundDraft){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)===outboundState.provider);outboundState.detail=await api(outboundState.provider==='gmail'?`/api/v1/integrations/${integration.id}/gmail/outbound-drafts/${button.dataset.outboundDraft}`:`/api/v1/integrations/ringcentral/${integration.id}/outbound/${button.dataset.outboundDraft}`);renderOutboundWorkspace();return;}if(button.dataset.ringcentralRefreshOutbound){const integration=outboundState.integrations.find(item=>integrationProvider(item.provider)==='ringcentral');await api(`/api/v1/integrations/ringcentral/${integration.id}/outbound/${button.dataset.ringcentralRefreshOutbound}/refresh`,'POST',{});await showOutboundWorkspace('ringcentral');notice('RingCentral provider status refreshed.');return;}if(button.dataset.openIntegrationInbox){closeIntegrationEditor();await showIntegrationInbox(button.dataset.openIntegrationInbox);return;}if(button.hasAttribute('data-open-ai-review')){closeIntegrationEditor();await showAiReviewWorkspace();return;}if(button.dataset.adapterTest==='ringcentral'){await api(`/api/v1/integrations/ringcentral/${button.dataset.id}/test`,'POST',{});notice('RingCentral account verified.');return;}if(button.dataset.ringcentralSubscribe){await api(`/api/v1/integrations/ringcentral/${button.dataset.ringcentralSubscribe}/subscription`,'POST',{transport:'websocket'});notice('RingCentral outbound live feed is starting.');return;}if(button.dataset.gmailSync){const result=await api(`/api/v1/integrations/${button.dataset.gmailSync}/gmail/sync`,'POST',{});notice(`${result.processed||0} Gmail change${result.processed===1?'':'s'} processed.`);return;}if(button.dataset.inboxTab){integrationInboxState.tab=button.dataset.inboxTab;integrationInboxState.detail=null;renderIntegrationInbox();return;}if(button.hasAttribute('data-refresh-integration-inbox')){await showIntegrationInbox(integrationInboxState.tab);return;}if(button.dataset.communicationEvent){const item=integrationRecord('ringcentral'),result=await api(`/api/v1/integrations/ringcentral/${item.id}/inbox/${button.dataset.communicationEvent}`);integrationInboxState.detail={type:'communications',integration:item.id,...result};renderIntegrationInbox();return;}if(button.dataset.referralEntry){const item=integrationRecord('gmail'),result=await api(`/api/v1/integrations/${item.id}/gmail/referrals/${button.dataset.referralEntry}`);integrationInboxState.detail={type:'referrals',integration:item.id,...result};renderIntegrationInbox();return;}if(button.hasAttribute('data-refresh-ai-review')){await showAiReviewWorkspace();return;}if(button.dataset.aiDraft){aiReviewState.detail=await api(`/api/v1/ai/drafts/${button.dataset.aiDraft}`);renderAiReview();}});
},true);
document.addEventListener('change',event=>{if(!event.target.matches?.('[data-ringcentral-kind]'))return;const form=event.target.form,kind=event.target.value;form.querySelector('[data-ringcentral-sms]').hidden=!['sms','ringout'].includes(kind);form.querySelector('[data-ringcentral-fax]').hidden=kind!=='fax';form.elements.sender.required=kind==='sms';form.elements.text.required=kind==='sms';form.elements.document.required=kind==='fax';});
